INSERT INTO t_p48987818_intercity_transfer_p.reviews (name, route, rating, text, approved) VALUES
('Андрей Соколов', 'Москва — Сочи', 5, 'Ехали семьёй с двумя детьми. Водитель подал машину минута в минуту, детские кресла были уже установлены. Цену назвали заранее и она не изменилась.', TRUE),
('Марина Егорова', 'Санкт-Петербург — Тверь', 5, 'Заказывала трансфер после ночного рейса. Встретили с табличкой, помогли с багажом. Машина чистая, в дороге тихо и комфортно — выспалась.', TRUE),
('Дмитрий Волков', 'Москва — Казань', 5, 'Пользуюсь регулярно для командировок. Дешевле агрегаторов, при этом уровень сервиса выше. Отдельный плюс — всегда можно дозвониться.', TRUE),
('Ольга Никитина', 'Москва — Нижний Новгород', 5, 'Везли кота в переноске, заранее предупредила — никаких проблем. Водитель делал остановки, когда просила. Рекомендую.', TRUE),
('Сергей Панин', 'Краснодар — Ростов-на-Дону', 5, 'Срочно нужна была доставка документов. Отправили в тот же день, забрали через два часа после звонка. Всё дошло в целости.', TRUE),
('Екатерина Лебедева', 'Москва — Ярославль', 5, 'Заказывали минивэн на компанию из семи человек. Все поместились с багажом, ехали с комфортом. Цена вышла ниже, чем на двух такси.', TRUE);
